{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret opfinder to former for handicaptillæg (tilrettelæggelsestillæg og meromkostningstillæg), som ikke findes i kilderne. Det angiver forkerte betingelser: 'erhvervsaktiverende dagpenge eller studiepenge' i stedet for almindelige SU-betingelser. Det udelader kravet om videregående uddannelse eller dansk EUD og kravet om varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de tre kritiske elementer er dækket. Almindelige SU-betingelser og udbetaling sammen med SU-stipendium eller slutlån nævnes ikke. Videregående uddannelse eller EUD nævnes ikke. Varig funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde nævnes ikke."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Svaret forsøger at angive betingelser, men indholdet er forkert og ikke hentet fra reglerne om handicaptillæg. Det besvarer derfor ikke i substans, hvad betingelserne er."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så kildestøtten kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer to typer tillæg, kravet om erhvervsaktiverende dagpenge eller studiepenge, kravet om særlige hjælpemidler og kravet om ekstra udgifter. Ingen af delene har støtte i de frosne kilder."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret fastholder ikke de væsentlige begrænsninger: varigheden af funktionsnedsættelsen, 'meget betydelige' begrænsninger og afgrænsningen til videregående uddannelse eller dansk EUD. Det nævner heller ikke, at de almindelige SU-betingelser ikke er udtømmende gengivet."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret er internt usammenhængende. Det siger, at begge tillæg kræver dagpenge eller studiepenge, men angiver derefter betingelser, der ikke hænger sammen med en konklusion om SU-handicaptillæg. Det tilføjer endda en tredje betingelse om 'begrænsning'/udgifter uden at forklare, hvordan de to former hænger sammen."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret bruger 'skal' om betingelser, som ikke findes i kilden, og gør dermed opfundne krav til absolutte betingelser. Det gengiver ikke kildernes 'skal' for de faktiske betingelser."}
  },
  "xhaile_coverage": {
    "A1": {"label": "no", "reason": "De almindelige SU- eller slutlånsbetingelser nævnes ikke. 'Erhvervsaktiverende dagpenge eller studiepenge' er en forkert betingelse."},
    "A2": {"label": "no", "reason": "Svaret nævner ikke krav om, at man går på en videregående uddannelse eller dansk EUD."},
    "A3": {"label": "no", "reason": "Svaret nævner ikke krav om varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde. 'Begrænsning' er kun vagt og knyttet til hjælpemidler, 'handicap eller sygdom' knyttet til ekstra udgifter."},
    "A4": {"label": "no", "reason": "Svaret nævner ikke indskrivning på og gennemførelse af en SU-berettigende uddannelse."},
    "A6": {"label": "no", "reason": "EUD, herunder EUX, og udelukkelsen af erhvervslignende uddannelse i udlandet nævnes ikke."}
  },
  "overall_notes": "Svaret er uden kilder og juridisk forkert. Det opfinder to typer tillæg og forkerte betingelser, og det udelader alle tre centrale betingelsesled i reglerne."
}

